		Address: wallet.Address,
	}
}

package middleware

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/dgraph-io/ristretto"
	"github.com/stellar/go-stellar-sdk/support/log"

	"github.com/stellar/stellar-disbursement-platform-backend/internal/data"
	"github.com/stellar/stellar-disbursement-platform-backend/internal/sdpcontext"
	"github.com/stellar/stellar-disbursement-platform-backend/internal/serve/httperror"
)

// apiKeyCacheTTL bounds how long a validated API key can be served from cache
// without a fresh DB check. It exists only as defense-in-depth (e.g. across
// multiple server instances, each with their own in-process cache); within a
// single instance, Invalidate is called synchronously by the API key
// handler on every permission/IP-allowlist change and on delete, so a given
// instance never needs to wait out the TTL to observe an update. Keep this
// short: it is a security control (permissions, IP allowlist), not a
// read-through cache for inert data, so a stale hit has real consequences.
const apiKeyCacheTTL = 10 * time.Second

// APIKeyAuthenticator authenticates SDP_-prefixed bearer tokens and caches
// validated keys - keyed by "<tenant ID>:<API key ID>", never by the raw
// secret and never by ID alone - so most requests avoid a DB round trip.
// Tenant-scoping the cache key prevents a raw key that is only valid for one
// tenant's schema from being served out of a cache entry warmed by a
// different tenant's context: the request's tenant comes from the
// attacker-controlled SDP-Tenant-Name header, so without this scoping a
// replayed key could ride another tenant's cached validation and bypass the
// schema-scoped DB lookup that is the sole mechanism binding a key to its
// tenant. Callers that mutate an API key's permissions, allowed IPs, or
// existence (update/delete) MUST call Invalidate(ctx, id) as part of that
// operation, or the cache can keep authorizing requests against the stale,
// pre-change permission set.
type APIKeyAuthenticator struct {
	model *data.APIKeyModel
	cache *ristretto.Cache
}

// NewAPIKeyAuthenticator builds an APIKeyAuthenticator backed by model.
func NewAPIKeyAuthenticator(model *data.APIKeyModel) *APIKeyAuthenticator {
	cache, err := ristretto.NewCache(&ristretto.Config{
		NumCounters: 10_000,
		MaxCost:     1_000,
		BufferItems: 64,
	})
	if err != nil {
		log.Errorf("Failed to create API key cache: %v", err)
		return &APIKeyAuthenticator{model: model}
	}

	cache.Wait()

	return &APIKeyAuthenticator{
		model: model,
		cache: cache,
	}
}

// cacheKeyFor builds the tenant-scoped cache key for the API key with the
// given ID, using the tenant resolved from ctx. ok is false (and key empty)
// when the tenant can't be resolved, in which case the cache must not be
// consulted at all - see validate for why.
func cacheKeyFor(ctx context.Context, id string) (key string, ok bool) {
	tenant, err := sdpcontext.GetTenantFromContext(ctx)
	if err != nil || tenant == nil || tenant.ID == "" {
		return "", false
	}
	return tenant.ID + ":" + id, true
}

// Invalidate evicts any cached validation result for the API key with the
// given ID, scoped to the tenant resolved from ctx (the same tenant the
// request that is updating/deleting the key is itself running under). It
// must be called whenever that key's permissions or allowed_ips are updated,
// or when the key is deleted, so the very next request using it is forced to
// re-fetch current authorization data from the DB instead of serving a stale
// cache hit.
func (a *APIKeyAuthenticator) Invalidate(ctx context.Context, id string) {
	if a == nil || a.cache == nil {
		return
	}
	if cacheKey, ok := cacheKeyFor(ctx, id); ok {
		a.cache.Del(cacheKey)
	}
}

func (a *APIKeyAuthenticator) validate(ctx context.Context, rawKey string) (*data.APIKey, error) {
	// The cache is keyed by "<tenant ID>:<API key ID>" rather than the raw
	// secret:
	//  - Tenant-scoping closes a cross-tenant cache-poisoning hole (see the
	//    type doc above): without it, a key cached while serving tenant A
	//    could be replayed under tenant B's name and served straight out of
	//    cache, bypassing the schema-scoped DB lookup that binds a key to
	//    its tenant.
	//  - Keying on the ID (not the secret) is what lets the /api-keys/{id}
	//    update/delete handlers evict exactly this entry: the raw secret is
	//    never persisted after creation, so those handlers have no way to
	//    derive it, only the ID.
	// The secret is still verified against the cached hash on every request
	// (cache hit or not), so a cache hit never skips authentication - it
	// only skips the DB round trip.
	id, secret, parseErr := data.ParseRawAPIKey(rawKey)

	var cacheKey string
	cacheable := false
	if parseErr == nil {
		cacheKey, cacheable = cacheKeyFor(ctx, id)
	}

	if a.cache == nil || !cacheable {
		apiKey, err := a.model.ValidateRawKeyAndUpdateLastUsed(ctx, rawKey)
		if err != nil {
			return nil, fmt.Errorf("validating API key (cacheless): %w", err)
		}
		return apiKey, nil
	}

	if cached, found := a.cache.Get(cacheKey); found {
		if apiKey, ok := cached.(*data.APIKey); ok &&
			!apiKey.IsExpired() &&
			apiKey.VerifySecret(secret) {
			return apiKey, nil
		}
		a.cache.Del(cacheKey)
	}

	apiKey, err := a.model.ValidateRawKeyAndUpdateLastUsed(ctx, rawKey)
	if err != nil {
		return nil, fmt.Errorf("validating API key: %w", err)
	}

	if !apiKey.IsExpired() {
		a.cache.SetWithTTL(cacheKey, apiKey, 1, apiKeyCacheTTL)
	}

	return apiKey, nil
}

func extractToken(r *http.Request) string {
	auth := r.Header.Get("Authorization")
	if parts := strings.Split(auth, " "); len(parts) == 2 {
		return parts[1]
	}
	return auth
}

func extractClientIP(r *http.Request) string {
	// Check proxy headers first
	for _, header := range []string{"X-Forwarded-For", "X-Real-IP"} {
		if ip := r.Header.Get(header); ip != "" {
			if comma := strings.Index(ip, ","); comma > 0 {
				ip = ip[:comma]
			}
			return strings.TrimSpace(ip)
		}
	}

	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil || host == "" {
		return r.RemoteAddr
	}
	return host
}

// Middleware first checks for an SDP_ key, then falls back to JWT.
func (a *APIKeyAuthenticator) Middleware(jwtAuth func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			token := extractToken(r)

			if !strings.HasPrefix(token, data.APIKeyPrefix) {
				jwtAuth(next).ServeHTTP(w, r)
				return
			}

			apiKey, err := a.validate(r.Context(), token)
			if err != nil {
				httperror.Unauthorized("Invalid API key", nil, nil).Render(w)
				return
			}

			if clientIP := extractClientIP(r); !apiKey.IsAllowedIP(clientIP) {
				httperror.Forbidden("IP not allowed", nil, nil).Render(w)
				return
			}

			// Set API key context
			ctx := r.Context()
			ctx = sdpcontext.SetAPIKeyInContext(ctx, apiKey)
			ctx = sdpcontext.SetUserIDInContext(ctx, apiKey.CreatedBy)
			ctx = log.Set(ctx, log.Ctx(ctx).WithField("user_id", apiKey.CreatedBy))

			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// APIKeyOrJWTAuthenticate builds a one-off APIKeyAuthenticator and returns its
// middleware. Prefer constructing an APIKeyAuthenticator once (via
// NewAPIKeyAuthenticator) and sharing it with whatever also needs to call
// Invalidate (e.g. the API key management handlers) - this helper is kept for
// callers (and tests) that don't need to invalidate the cache themselves.
func APIKeyOrJWTAuthenticate(apiKeyModel *data.APIKeyModel, jwtAuth func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return NewAPIKeyAuthenticator(apiKeyModel).Middleware(jwtAuth)
}

// RequirePermission ensures the caller has the given APIKeyPermission or (if no APIKey in context) passes through to the next role-check.
func RequirePermission(perm data.APIKeyPermission, jwtCheck func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// --- API key path ---
			if apiKey, err := sdpcontext.GetAPIKeyFromContext(r.Context()); err == nil {
				if !apiKey.HasPermission(perm) {
					httperror.Forbidden("Insufficient API key permissions", nil, nil).Render(w)
					return
				}
				next.ServeHTTP(w, r)
				return
			}
			// --- JWT path: delegate ---
			jwtCheck(next).ServeHTTP(w, r)
		})
	}
}

package httpresponse

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// PaginatedResponse is a response that contains pagination information.
type PaginatedResponse struct {
	Pagination PaginationInfo  `json:"pagination"`
	Data       json.RawMessage `json:"data"`
}

type PaginationInfo struct {
	Next  string `json:"next,omitempty"`
	Prev  string `json:"prev,omitempty"`
	Pages int    `json:"pages"`
	Total int    `json:"total"`
}

// NewEmptyPaginatedResponse returns a PaginatedResponse with an empty data and 0 pages.
//
//	This is useful for returning an empty list.
func NewEmptyPaginatedResponse() PaginatedResponse {
	return PaginatedResponse{
		Pagination: PaginationInfo{
			Pages: 0,
			Total: 0,
		},
		Data: json.RawMessage("[]"),
	}
}

// NewPaginatedResponse returns a PaginatedResponse with pagination information.
func NewPaginatedResponse(r *http.Request, data interface{}, currentPage, pageLimit, totalItems int) (PaginatedResponse, error) {
	if pageLimit <= 0 {
		return PaginatedResponse{}, fmt.Errorf("page_limit must be a positive integer")
	}
	totalPages := (totalItems + pageLimit - 1) / pageLimit
	pagination := PaginationInfo{Pages: totalPages, Total: totalItems}

	baseURL := *r.URL
	q := baseURL.Query()
	q.Del("page")

	if currentPage < totalPages {
		q.Set("page", fmt.Sprintf("%d", currentPage+1))
		baseURL.RawQuery = q.Encode()
		pagination.Next = baseURL.String()
	}

	if currentPage > 1 {
		q.Set("page", fmt.Sprintf("%d", currentPage-1))
		baseURL.RawQuery = q.Encode()
		pagination.Prev = baseURL.String()
	}

	dataBytes, err := json.Marshal(data)
	if err != nil {
		return PaginatedResponse{}, fmt.Errorf("marshalling data: %w", err)
	}

	return PaginatedResponse{
		Pagination: pagination,
		Data:       dataBytes,
	}, nil
}

package validators

import (
	"fmt"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/stellar/stellar-disbursement-platform-backend/internal/data"
)

type QueryValidator struct {
	*Validator
	DefaultSortField  data.SortField
	DefaultSortOrder  data.SortOrder
	AllowedSortFields []data.SortField
	AllowedFilters    []data.FilterKey
}

const (
	DefaultPageLimit = 20
	MaxPageLimit     = 100
)

// ParseParametersFromRequest parses query parameters from the request and returns a QueryParams struct.
func (qv *QueryValidator) ParseParametersFromRequest(r *http.Request) *data.QueryParams {
	page := qv.validateAndGetIntParams(r, "page", 1)
	pageLimit := qv.validateAndGetIntParams(r, "page_limit", DefaultPageLimit)

	query := r.URL.Query()
	sortBy := data.SortField(query.Get("sort"))
	if sortBy == "" {
		sortBy = qv.DefaultSortField
	} else if !slices.Contains(qv.AllowedSortFields, sortBy) {
		qv.AddError("sort", "invalid sort field name")
	}

	sortOrder := data.SortOrder(strings.ToUpper(query.Get("direction")))
	if sortOrder == "" {
		sortOrder = qv.DefaultSortOrder
	} else if sortOrder != data.SortOrderASC && sortOrder != data.SortOrderDESC {
		qv.AddError("direction", "invalid sort order. valid values are 'asc' and 'desc'")
	}

	filters := make(map[data.FilterKey]any)
	for _, fk := range qv.AllowedFilters {
		value := strings.TrimSpace(query.Get(string(fk)))
		if value != "" {
			filters[fk] = value
		}
	}

	ok := slices.Contains(qv.AllowedFilters, data.FilterKeyPaymentType)

	if paymentType := query.Get("type"); ok && paymentType != "" {
		filters[data.FilterKeyPaymentType] = paymentType
	}

	if qv.HasErrors() {
		return &data.QueryParams{}
	}

	return &data.QueryParams{
		Query:     strings.TrimSpace(query.Get("q")),
		Page:      page,
		PageLimit: pageLimit,
		SortBy:    sortBy,
		SortOrder: sortOrder,
		Filters:   filters,
	}
}

// validateAndGetIntParams validates the query parameter and returns the value as an integer.
func (qv *QueryValidator) validateAndGetIntParams(r *http.Request, param string, defaultValue int) int {
	value := r.URL.Query().Get(param)
	if value == "" {
		return defaultValue
	}

	intValue, err := strconv.Atoi(value)
	if err != nil {
		qv.CheckError(err, param, "parameter must be an integer")
		return defaultValue
	}

	if intValue <= 0 {
		qv.AddError(param, "parameter must be a positive integer")
		return defaultValue
	}

	if param == "page_limit" && intValue > MaxPageLimit {
		qv.AddError(param, fmt.Sprintf("parameter must be less than or equal to %d", MaxPageLimit))
		return defaultValue
	}

	return intValue
}

// ValidateAndGetTimeParams validates the query parameter and returns the value as a time.Time.
func (qv *QueryValidator) ValidateAndGetTimeParams(param string, value interface{}) time.Time {
	if value == nil {
		return time.Time{}
	}

	dateStr, ok := value.(string)
	if !ok {
		qv.Check(false, param, "invalid date format. valid format is 'YYYY-MM-DD'")
		return time.Time{}
	}

	dateParam, err := time.Parse("2006-01-02", dateStr)
	if err != nil {
		qv.Check(false, param, "invalid date format. valid format is 'YYYY-MM-DD'")
		return time.Time{}
	}

	return dateParam
}

package validators

import (
	"fmt"
	"slices"
	"strings"

	"github.com/stellar/stellar-disbursement-platform-backend/internal/data"
)

type PaymentQueryValidator struct {
	QueryValidator
}

// NewPaymentQueryValidator creates a new PaymentQueryValidator with the provided configuration.
func NewPaymentQueryValidator() *PaymentQueryValidator {
	return &PaymentQueryValidator{
		QueryValidator: QueryValidator{
			DefaultSortField:  data.DefaultPaymentSortField,
			DefaultSortOrder:  data.DefaultPaymentSortOrder,
			AllowedSortFields: data.AllowedPaymentSorts,
			AllowedFilters:    data.AllowedPaymentFilters,
			Validator:         NewValidator(),
		},
	}
}

// ValidateAndGetPaymentFilters validates the filters and returns a map of valid filters.
func (qv *PaymentQueryValidator) ValidateAndGetPaymentFilters(filters map[data.FilterKey]any) map[data.FilterKey]any {
	validFilters := make(map[data.FilterKey]any)
	if filters[data.FilterKeyStatus] != nil {
		validFilters[data.FilterKeyStatus] = qv.validateAndGetPaymentStatus(filters[data.FilterKeyStatus].(string))
	}
	if filters[data.FilterKeyReceiverID] != nil {
		validFilters[data.FilterKeyReceiverID] = filters[data.FilterKeyReceiverID]
	}
	if filters[data.FilterKeyPaymentType] != nil {
		validFilters[data.FilterKeyPaymentType] = qv.validateAndGetPaymentType(filters[data.FilterKeyPaymentType].(string))
	}

	createdAtAfter := qv.ValidateAndGetTimeParams(string(data.FilterKeyCreatedAtAfter), filters[data.FilterKeyCreatedAtAfter])
	createdAtBefore := qv.ValidateAndGetTimeParams(string(data.FilterKeyCreatedAtBefore), filters[data.FilterKeyCreatedAtBefore])

	if qv.HasErrors() {
		return validFilters
	}

	if !createdAtAfter.IsZero() && !createdAtBefore.IsZero() {
		qv.Check(createdAtAfter.Before(createdAtBefore), string(data.FilterKeyCreatedAtAfter), "created_at_after must be before created_at_before")
	}

	if !createdAtAfter.IsZero() {
		validFilters[data.FilterKeyCreatedAtAfter] = createdAtAfter
	}
	if !createdAtBefore.IsZero() {
		validFilters[data.FilterKeyCreatedAtBefore] = createdAtBefore
	}
	return validFilters
}

// validateAndGetPaymentStatus validates the status parameter and returns the corresponding PaymentStatus.
func (qv *PaymentQueryValidator) validateAndGetPaymentStatus(status string) data.PaymentStatus {
	s := data.PaymentStatus(strings.ToUpper(status))
	if slices.Contains(data.PaymentStatuses(), s) {
		return s
	}

	qv.Check(false, string(data.FilterKeyStatus), fmt.Sprintf("invalid parameter. valid values are: %v", data.PaymentStatuses()))
	return ""
}

func (qv *PaymentQueryValidator) validateAndGetPaymentType(typeParam string) data.PaymentType {
	switch strings.ToUpper(strings.TrimSpace(typeParam)) {
	case "DIRECT":
		return data.PaymentTypeDirect
	case "DISBURSEMENT":
		return data.PaymentTypeDisbursement
	default:
		qv.Check(false, string(data.FilterKeyPaymentType), fmt.Sprintf("invalid payment type '%s'. Must be 'direct' or 'disbursement'", typeParam))
		return ""
	}
}

package validators

import (
	"strings"

	"github.com/stellar/stellar-disbursement-platform-backend/internal/data"
)

type DisbursementQueryValidator struct {
	QueryValidator
}

// NewDisbursementQueryValidator creates a new DisbursementQueryValidator with the provided configuration.
func NewDisbursementQueryValidator() *DisbursementQueryValidator {
	return &DisbursementQueryValidator{
		QueryValidator: QueryValidator{
			DefaultSortField:  data.DefaultDisbursementSortField,
			DefaultSortOrder:  data.DefaultDisbursementSortOrder,
			AllowedSortFields: data.AllowedDisbursementSorts,
			AllowedFilters:    data.AllowedDisbursementFilters,
			Validator:         NewValidator(),
		},
	}
}

// ValidateAndGetDisbursementFilters validates the filters and returns a map of valid filters.
func (qv *DisbursementQueryValidator) ValidateAndGetDisbursementFilters(filters map[data.FilterKey]interface{}) map[data.FilterKey]interface{} {
	validFilters := make(map[data.FilterKey]interface{})
	if filters[data.FilterKeyStatus] != nil {
		validFilters[data.FilterKeyStatus] = qv.validateAndGetDisbursementStatuses(filters[data.FilterKeyStatus].(string))
	}

	createdAtAfter := qv.ValidateAndGetTimeParams(string(data.FilterKeyCreatedAtAfter), filters[data.FilterKeyCreatedAtAfter])
	createdAtBefore := qv.ValidateAndGetTimeParams(string(data.FilterKeyCreatedAtBefore), filters[data.FilterKeyCreatedAtBefore])

	if qv.HasErrors() {
		return validFilters
	}

	if !createdAtAfter.IsZero() && !createdAtBefore.IsZero() {
		qv.Check(createdAtAfter.Before(createdAtBefore), string(data.FilterKeyCreatedAtAfter), "created_at_after must be before created_at_before")
	}

	if !createdAtAfter.IsZero() {
		validFilters[data.FilterKeyCreatedAtAfter] = createdAtAfter
	}
	if !createdAtBefore.IsZero() {
		validFilters[data.FilterKeyCreatedAtBefore] = createdAtBefore
	}
	return validFilters
}

// validateAndGetDisbursementStatuses takes a comma-separated string of disbursement statuses
// and returns a slice of valid DisbursementStatus values.
func (qv *DisbursementQueryValidator) validateAndGetDisbursementStatuses(statuses string) []data.DisbursementStatus {
	statusList := strings.Split(statuses, ",")
	validStatuses := []data.DisbursementStatus{}

	for _, status := range statusList {
		s := data.DisbursementStatus(strings.ToUpper(strings.TrimSpace(status)))
		switch s {
		case data.DraftDisbursementStatus, data.ReadyDisbursementStatus, data.StartedDisbursementStatus, data.PausedDisbursementStatus, data.CompletedDisbursementStatus, data.CanceledDisbursementStatus:
			validStatuses = append(validStatuses, s)
		default:
			qv.Check(false, string(data.FilterKeyStatus), "invalid parameter. valid value is a comma separate list of statuses: draft, ready, started, paused, completed, canceled")
		}
	}
	return validStatuses
}

package schema

import (
	"encoding/hex"
	"fmt"
	"strconv"

	"github.com/stellar/go-stellar-sdk/txnbuild"
)

type Memo struct {
	Value string
	Type  MemoType
}

type MemoType string

const (
	MemoTypeText   MemoType = "text"
	MemoTypeID     MemoType = "id"
	MemoTypeHash   MemoType = "hash"
	MemoTypeReturn MemoType = "return"
)

// NewMemo creates a new Memo from a MemoType and a string value.
func NewMemo(memoType MemoType, memoValue string) (txnbuild.Memo, error) {
	switch memoType {
	case "":
		return nil, nil

	case MemoTypeID:
		// Memo ID (uint64)
		id, err := strconv.ParseUint(memoValue, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("invalid Memo ID value, must be a uint64: %w", err)
		}
		return txnbuild.MemoID(id), nil

	case MemoTypeText:
		// Memo Text (up to 28 bytes)
		if len(memoValue) > 28 {
			return nil, fmt.Errorf("text memo must be 28 bytes or less")
		}
		return txnbuild.MemoText(memoValue), nil

	case MemoTypeHash:
		// Memo Hash (32-byte hash)
		if len(memoValue) != 64 {
			return nil, fmt.Errorf("hash memo must be 64 hex characters (32 bytes)")
		}
		hashBytes, err := hexStringToBytes(memoValue)
		if err != nil {
			return nil, fmt.Errorf("invalid hash format: %w", err)
		}
		return txnbuild.MemoHash(hashBytes), nil

	case MemoTypeReturn:
		// Memo Return (32-byte hash)
		if len(memoValue) != 64 {
			return nil, fmt.Errorf("return memo must be 64 hex characters (32 bytes)")
		}
		hashBytes, err := hexStringToBytes(memoValue)
		if err != nil {
			return nil, fmt.Errorf("invalid return hash format: %w", err)
		}
		return txnbuild.MemoReturn(hashBytes), nil

	default:
		return nil, fmt.Errorf("unknown memo type: %s", memoType)
	}
}

// hexStringToBytes is a utility function to convert a hex string to a byte slice.
func hexStringToBytes(hexStr string) ([]byte, error) {
	bytes, err := hex.DecodeString(hexStr)
	if err != nil {
		return nil, fmt.Errorf("decoding hex string %s: %w", hexStr, err)
	}
	return bytes, nil
}

// ParseMemo attempts to detect and parse a string into a Stellar memo by trying all possible memo types.
// It returns the parsed memo and detected memo type, or any error that occurred.
func ParseMemo(memoValue string) (txnbuild.Memo, MemoType, error) {
	if memoValue == "" {
		return nil, "", nil
	}

	for _, memoType := range []MemoType{MemoTypeID, MemoTypeText, MemoTypeHash} {
		if memo, err := NewMemo(memoType, memoValue); err == nil {
			return memo, memoType, nil
		}
	}

	return nil, "", fmt.Errorf("could not parse value %q as any valid memo type", memoValue)
}
